## 解题思路\n\n对于节点 $i$，若选择两个后代节点 $u,v$，满足：\n\n$LCA(u,v)=i$\n\n$dist(u,i)=dist(v,i)=d$\n\n那么路径 $u \\to v$ 的点数为：\n\n$2d+1$\n\n要让路径上的字符串满足条件，以 $i$ 为中心，两边字符必须一层一层相同。\n\n也就是说，从 $i$ 的某两个不同儿子子树中，向下走 $d$ 层得到的字符串必须完全相同。\n\n因此问题可以转化为：\n\n对于每个节点 $i$，求它的不同儿子子树中，是否存在两条长度为 $d$ 的向下路径字符串相同，最大化 $2d+1$。\n\n核心做法：\n\n使用树上字符串哈希。\n\n设根到节点 $x$ 的字符串哈希为 $H_x$，深度为 $dep_x$。\n\n对于一个节点 $i$ 和它的后代 $x$，可以 $O(1)$ 求出从 $i$ 的儿子到 $x$ 这段向下字符串的哈希值。\n\n然后使用启发式合并：\n\n对于每个节点 $i$，枚举它的儿子子树。\n\n维护一个哈希表，记录已经处理过的儿子子树中出现过的：\n\n$(相对深度, 字符串哈希)$\n\n当处理新的儿子子树时，先查询是否已经出现过相同的键，如果出现，说明可以组成一个以 $i$ 为中心的镜像三元组。\n\n为了保证复杂度，使用小并大思想，每个节点所在的小子树只会被枚举 $O(\\log n)$ 次。\n\n最终答案至少为 $1$，因为可以选择 $u=v=i$，路径只有一个点，一定是合法的镜像三元组。\n\n相关算法：\n\n树形 DFS、倍增祖先、字符串哈希、启发式合并。\n\n## 复杂度分析\n\n设节点数为 $n$。\n\n每个节点在启发式合并过程中被枚举 $O(\\log n)$ 次。\n\n时间复杂度为：\n\n$O(n \\log n)$\n\n需要存储树、深度、哈希、倍增数组和辅助哈希表。\n\n空间复杂度为：\n\n$O(n \\log n)$\n\n## 代码实现\n\n### Python\n\n```python\nimport sys\nsys.setrecursionlimit(300000)\n\nMOD1 = 1000000007\nMOD2 = 1000000009\nBASE = 911382323\n\ndef solve(n, s, edges):\n    g = [[] for _ in range(n + 1)]\n    for u, v in edges:\n        g[u].append(v)\n        g[v].append(u)\n\n    LOG = 18\n    fa = [[0] * (n + 1) for _ in range(LOG)]\n    dep = [0] * (n + 1)\n    size = [1] * (n + 1)\n    son = [0] * (n + 1)\n\n    h1 = [0] * (n + 1)\n    h2 = [0] * (n + 1)\n    pow1 = [1] * (n + 2)\n    pow2 = [1] * (n + 2)\n\n    for i in range(1, n + 2):\n        pow1[i] = pow1[i - 1] * BASE % MOD1\n        pow2[i] = pow2[i - 1] * BASE % MOD2\n\n    order = [1]\n    fa[0][1] = 0\n\n    # 建树并求父亲、深度和根到点哈希\n    for u in order:\n        for v in g[u]:\n            if v == fa[0][u]:\n                continue\n            fa[0][v] = u\n            dep[v] = dep[u] + 1\n            c = ord(s[v - 1]) - ord('a') + 1\n            h1[v] = (h1[u] * BASE + c) % MOD1\n            h2[v] = (h2[u] * BASE + c) % MOD2\n            order.append(v)\n\n    # 倍增父亲\n    for k in range(1, LOG):\n        for i in range(1, n + 1):\n            fa[k][i] = fa[k - 1][fa[k - 1][i]]\n\n    # 求子树大小和重儿子\n    for u in reversed(order):\n        size[u] = 1\n        for v in g[u]:\n            if v == fa[0][u]:\n                continue\n            size[u] += size[v]\n            if size[v] > size[son[u]]:\n                son[u] = v\n\n    dfn = [0] * (n + 1)\n    rev = [0] * (n + 1)\n    timer = 0\n\n    # DFS 序，方便枚举子树\n    def dfs_dfn(u):\n        nonlocal timer\n        timer += 1\n        dfn[u] = timer\n        rev[timer] = u\n        for v in g[u]:\n            if v != fa[0][u]:\n                dfs_dfn(v)\n\n    dfs_dfn(1)\n\n    ans = [1] * (n + 1)\n\n    # 求 ancestor 到 x 的下一层后到 x 的字符串哈希\n    def get_hash(ancestor, x):\n        length = dep[x] - dep[ancestor]\n        a = ancestor\n        v1 = (h1[x] - h1[a] * pow1[length]) % MOD1\n        v2 = (h2[x] - h2[a] * pow2[length]) % MOD2\n        return v1, v2\n\n    # 枚举子树中的所有节点\n    def nodes_in_subtree(u):\n        for i in range(dfn[u], dfn[u] + size[u]):\n            yield rev[i]\n\n    # 递归处理每个节点\n    def dfs(u):\n        for v in g[u]:\n            if v != fa[0][u]:\n                dfs(v)\n\n        mp = {}\n\n        # 先加入重儿子子树，减少总枚举次数\n        if son[u]:\n            for x in nodes_in_subtree(son[u]):\n                d = dep[x] - dep[u]\n                key = (d, get_hash(u, x))\n                mp[key] = son[u]\n\n        # 处理其他儿子子树\n        for v in g[u]:\n            if v == fa[0][u] or v == son[u]:\n                continue\n\n            # 先查询，避免同一儿子子树内部互相匹配\n            for x in nodes_in_subtree(v):\n                d = dep[x] - dep[u]\n                key = (d, get_hash(u, x))\n                if key in mp and mp[key] != v:\n                    ans[u] = max(ans[u], 2 * d + 1)\n\n            # 再加入当前儿子子树\n            for x in nodes_in_subtree(v):\n                d = dep[x] - dep[u]\n                key = (d, get_hash(u, x))\n                mp[key] = v\n\n    dfs(1)\n    return ans[1:]\n\n\ndef main():\n    input = sys.stdin.readline\n    n = int(input())\n    s = input().strip()\n\n    edges = []\n    for _ in range(n - 1):\n        u, v = map(int, input().split())\n        edges.append((u, v))\n\n    ans = solve(n, s, edges)\n    print(*ans)\n\n\nif __name__ == \"__main__\":\n    main()\n```\n\n### Java\n\n```java\nimport java.util.*;\n\npublic class Main {\n    static final long MOD1 = 1000000007L;\n    static final long MOD2 = 1000000009L;\n    static final long BASE = 911382323L;\n\n    static int n, LOG = 18, timer = 0;\n    static String str;\n    static ArrayList<Integer>[] g;\n    static int[][] fa;\n    static int[] dep, size, son, dfn, rev, ans;\n    static long[] h1, h2, pow1, pow2;\n\n    // 哈希键\n    static class Key {\n        int depth;\n        long a, b;\n\n        Key(int depth, long a, long b) {\n            this.depth = depth;\n            this.a = a;\n            this.b = b;\n        }\n\n        public boolean equals(Object o) {\n            if (!(o instanceof Key)) return false;\n            Key k = (Key) o;\n            return depth == k.depth && a == k.a && b == k.b;\n        }\n\n        public int hashCode() {\n            long res = depth;\n            res = res * 1000003 + a;\n            res = res * 1000003 + b;\n            return (int)(res ^ (res >>> 32));\n        }\n    }\n\n    // 建树，求父亲、深度、哈希\n    static void build() {\n        int[] q = new int[n];\n        int head = 0, tail = 0;\n        q[tail++] = 1;\n\n        while (head < tail) {\n            int u = q[head++];\n            for (int v : g[u]) {\n                if (v == fa[0][u]) continue;\n                fa[0][v] = u;\n                dep[v] = dep[u] + 1;\n\n                int c = str.charAt(v - 1) - 'a' + 1;\n                h1[v] = (h1[u] * BASE + c) % MOD1;\n                h2[v] = (h2[u] * BASE + c) % MOD2;\n\n                q[tail++] = v;\n            }\n        }\n\n        // 倍增父亲\n        for (int k = 1; k < LOG; k++) {\n            for (int i = 1; i <= n; i++) {\n                fa[k][i] = fa[k - 1][fa[k - 1][i]];\n            }\n        }\n\n        // 求子树大小和重儿子\n        for (int i = n - 1; i >= 0; i--) {\n            int u = q[i];\n            size[u] = 1;\n            for (int v : g[u]) {\n                if (v == fa[0][u]) continue;\n                size[u] += size[v];\n                if (son[u] == 0 || size[v] > size[son[u]]) {\n                    son[u] = v;\n                }\n            }\n        }\n    }\n\n    // 求 DFS 序\n    static void dfsDfn(int u) {\n        dfn[u] = ++timer;\n        rev[timer] = u;\n\n        for (int v : g[u]) {\n            if (v != fa[0][u]) {\n                dfsDfn(v);\n            }\n        }\n    }\n\n    // 求 ancestor 的下一层到 x 的字符串哈希\n    static Key getKey(int ancestor, int x) {\n        int len = dep[x] - dep[ancestor];\n\n        long a = (h1[x] - h1[ancestor] * pow1[len]) % MOD1;\n        if (a < 0) a += MOD1;\n\n        long b = (h2[x] - h2[ancestor] * pow2[len]) % MOD2;\n        if (b < 0) b += MOD2;\n\n        return new Key(len, a, b);\n    }\n\n    // 处理每个节点\n    static void dfs(int u) {\n        for (int v : g[u]) {\n            if (v != fa[0][u]) {\n                dfs(v);\n            }\n        }\n\n        HashMap<Key, Integer> map = new HashMap<>();\n\n        // 先加入重儿子子树\n        if (son[u] != 0) {\n            int v = son[u];\n            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {\n                int x = rev[i];\n                Key key = getKey(u, x);\n                map.put(key, v);\n            }\n        }\n\n        // 再处理轻儿子子树\n        for (int v : g[u]) {\n            if (v == fa[0][u] || v == son[u]) continue;\n\n            // 先查询是否能与之前儿子子树匹配\n            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {\n                int x = rev[i];\n                Key key = getKey(u, x);\n\n                if (map.containsKey(key) && map.get(key) != v) {\n                    int d = dep[x] - dep[u];\n                    ans[u] = Math.max(ans[u], 2 * d + 1);\n                }\n            }\n\n            // 再加入当前儿子子树\n            for (int i = dfn[v]; i < dfn[v] + size[v]; i++) {\n                int x = rev[i];\n                Key key = getKey(u, x);\n                map.put(key, v);\n            }\n        }\n    }\n\n    static int[] solve() {\n        pow1 = new long[n + 2];\n        pow2 = new long[n + 2];\n        pow1[0] = pow2[0] = 1;\n\n        for (int i = 1; i <= n + 1; i++) {\n            pow1[i] = pow1[i - 1] * BASE % MOD1;\n            pow2[i] = pow2[i - 1] * BASE % MOD2;\n        }\n\n        build();\n        dfsDfn(1);\n\n        Arrays.fill(ans, 1);\n        dfs(1);\n\n        return ans;\n    }\n\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n\n        n = sc.nextInt();\n        str = sc.next();\n\n        g = new ArrayList[n + 1];\n        for (int i = 1; i <= n; i++) {\n            g[i] = new ArrayList<>();\n        }\n\n        for (int i = 1; i < n; i++) {\n            int u = sc.nextInt();\n            int v = sc.nextInt();\n            g[u].add(v);\n            g[v].add(u);\n        }\n\n        fa = new int[LOG][n + 1];\n        dep = new int[n + 1];\n        size = new int[n + 1];\n        son = new int[n + 1];\n        dfn = new int[n + 1];\n        rev = new int[n + 1];\n        ans = new int[n + 1];\n        h1 = new long[n + 1];\n        h2 = new long[n + 1];\n\n        int[] res = solve();\n\n        StringBuilder sb = new StringBuilder();\n        for (int i = 1; i <= n; i++) {\n            if (i > 1) sb.append(' ');\n            sb.append(res[i]);\n        }\n        System.out.println(sb);\n    }\n}\n```\n\n### C++\n\n```cpp\n#include <bits/stdc++.h>\nusing namespace std;\n\nconst long long MOD1 = 1000000007LL;\nconst long long MOD2 = 1000000009LL;\nconst long long BASE = 911382323LL;\n\nstruct Key {\n    int d;\n    long long a, b;\n\n    bool operator==(const Key& other) const {\n        return d == other.d && a == other.a && b == other.b;\n    }\n};\n\n// 自定义哈希函数\nstruct KeyHash {\n    size_t operator()(const Key& k) const {\n        long long res = k.d;\n        res = res * 1000003 + k.a;\n        res = res * 1000003 + k.b;\n        return (size_t)(res ^ (res >> 32));\n    }\n};\n\nint n, LOG = 18, timerCnt = 0;\nstring s;\nvector<vector<int>> g;\nvector<vector<int>> fa;\nvector<int> dep, sz, son, dfn, rev, ans;\nvector<long long> h1, h2, pow1, pow2;\n\n// 建树，求父亲、深度、哈希、子树大小和重儿子\nvoid build() {\n    vector<int> order;\n    order.push_back(1);\n\n    for (int i = 0; i < (int)order.size(); i++) {\n        int u = order[i];\n\n        for (int v : g[u]) {\n            if (v == fa[0][u]) continue;\n\n            fa[0][v] = u;\n            dep[v] = dep[u] + 1;\n\n            int c = s[v - 1] - 'a' + 1;\n            h1[v] = (h1[u] * BASE + c) % MOD1;\n            h2[v] = (h2[u] * BASE + c) % MOD2;\n\n            order.push_back(v);\n        }\n    }\n\n    // 倍增父亲\n    for (int k = 1; k < LOG; k++) {\n        for (int i = 1; i <= n; i++) {\n            fa[k][i] = fa[k - 1][fa[k - 1][i]];\n        }\n    }\n\n    // 求子树大小和重儿子\n    for (int i = n - 1; i >= 0; i--) {\n        int u = order[i];\n        sz[u] = 1;\n\n        for (int v : g[u]) {\n            if (v == fa[0][u]) continue;\n\n            sz[u] += sz[v];\n            if (son[u] == 0 || sz[v] > sz[son[u]]) {\n                son[u] = v;\n            }\n        }\n    }\n}\n\n// 求 DFS 序\nvoid dfsDfn(int u) {\n    dfn[u] = ++timerCnt;\n    rev[timerCnt] = u;\n\n    for (int v : g[u]) {\n        if (v != fa[0][u]) {\n            dfsDfn(v);\n        }\n    }\n}\n\n// 求 ancestor 的下一层到 x 的字符串哈希\nKey getKey(int ancestor, int x) {\n    int len = dep[x] - dep[ancestor];\n\n    long long a = (h1[x] - h1[ancestor] * pow1[len]) % MOD1;\n    if (a < 0) a += MOD1;\n\n    long long b = (h2[x] - h2[ancestor] * pow2[len]) % MOD2;\n    if (b < 0) b += MOD2;\n\n    return {len, a, b};\n}\n\n// 递归处理答案\nvoid dfs(int u) {\n    for (int v : g[u]) {\n        if (v != fa[0][u]) {\n            dfs(v);\n        }\n    }\n\n    unordered_map<Key, int, KeyHash> mp;\n\n    // 先加入重儿子子树\n    if (son[u]) {\n        int v = son[u];\n\n        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {\n            int x = rev[i];\n            Key key = getKey(u, x);\n            mp[key] = v;\n        }\n    }\n\n    // 处理轻儿子子树\n    for (int v : g[u]) {\n        if (v == fa[0][u] || v == son[u]) continue;\n\n        // 先查询，避免同一儿子子树内部匹配\n        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {\n            int x = rev[i];\n            Key key = getKey(u, x);\n\n            if (mp.find(key) != mp.end() && mp[key] != v) {\n                int d = dep[x] - dep[u];\n                ans[u] = max(ans[u], 2 * d + 1);\n            }\n        }\n\n        // 再加入当前儿子子树\n        for (int i = dfn[v]; i < dfn[v] + sz[v]; i++) {\n            int x = rev[i];\n            Key key = getKey(u, x);\n            mp[key] = v;\n        }\n    }\n}\n\nvector<int> solve() {\n    pow1.assign(n + 2, 1);\n    pow2.assign(n + 2, 1);\n\n    for (int i = 1; i <= n + 1; i++) {\n        pow1[i] = pow1[i - 1] * BASE % MOD1;\n        pow2[i] = pow2[i - 1] * BASE % MOD2;\n    }\n\n    build();\n    dfsDfn(1);\n\n    ans.assign(n + 1, 1);\n    dfs(1);\n\n    return ans;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n\n    cin >> n;\n    cin >> s;\n\n    g.assign(n + 1, vector<int>());\n\n    for (int i = 1; i < n; i++) {\n        int u, v;\n        cin >> u >> v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n    }\n\n    fa.assign(LOG, vector<int>(n + 1, 0));\n    dep.assign(n + 1, 0);\n    sz.assign(n + 1, 0);\n    son.assign(n + 1, 0);\n    dfn.assign(n + 1, 0);\n    rev.assign(n + 1, 0);\n    h1.assign(n + 1, 0);\n    h2.assign(n + 1, 0);\n\n    vector<int> res = solve();\n\n    for (int i = 1; i <= n; i++) {\n        if (i > 1) cout << ' ';\n        cout << res[i];\n    }\n    cout << '\\n';\n\n    return 0;\n}\n```